use verus::prelude::*;

verus! {

    /// Given a vector of non‐empty integer vectors `lst`,
    /// returns a new vector whose i-th element is the first
    /// element of `lst[i]`.
    ///
    /// Requires:
    ///   - Every inner vector is non‐empty.
    /// Ensures:
    ///   - The result has the same length as `lst`.
    ///   - For every valid index `i`, `result[i] == lst[i][0]`.
    fn get_first_elements(lst: Vec<Vec<int>>) -> Vec<int>
        // Precondition: each inner vector has length > 0
        requires(forall |i: usize| i < lst.len() ==> lst[i].len() > 0)
        // Postcondition: output length matches input length
        ensures(|result: &Vec<int>| result.len() == lst.len())
        // Postcondition: output[i] == lst[i][0]
        ensures(|result: &Vec<int>|
            forall(|i: usize| i < result.len() ==> result[i] == lst[i][0]))
    {
        // Allocate an empty vector and reserve room for all the first elements
        let mut result: Vec<int> = Vec::new();
        result.reserve(lst.len());

        // Iterate over lst, index by index
        let mut i: usize = 0;
        while i < lst.len() {
            // Invariants to carry through the loop:
            // 1) 0 <= i <= lst.len()
            // 2) result.len() == i
            // 3) for all j < i, result[j] == lst[j][0]
            invariant(i <= lst.len());
            invariant(result.len() == i);
            invariant(forall(|j: usize| j < i ==> result[j] == lst[j][0]));
            decreases(lst.len() - i);

            // Safe to index because of the loop guard and precondition
            let first_elem: int = lst[i][0];
            result.push(first_elem);
            i += 1;
        }

        result
    }

}